import{_ as o,b as a,c as e,I as n}from"./chunks/framework.C6cPs9Ia.js";const d=JSON.parse('{"title":"上学路上的 23 分钟歌单","description":"高中生的上学路歌单分享——23 分钟的车程与每首歌的小故事","frontmatter":{"title":"上学路上的 23 分钟歌单","date":"2026-07-22T00:00:00.000Z","tags":["音乐","歌单","日常"],"cover":"/LQY/images/cover-c.jpg","head":[["meta",{"name":"description","content":"高中生的上学路歌单分享——23 分钟的车程与每首歌的小故事"}],["meta",{"name":"keywords","content":"歌单, 通勤, 音乐分享, 日常"}]]},"headers":[],"relativePath":"posts/commute-playlist.md","filePath":"posts/commute-playlist.md"}'),r={name:"posts/commute-playlist.md"};function s(i,t,l,p,m,c){return a(),e("div",null,[...t[0]||(t[0]=[n('<p>家和学校之间隔 23 分钟公交。这个长度很微妙：不长不短，正好几张歌的量。</p><p>所以我的歌单是按&quot;23 分钟一循环&quot;设计的。以下是目前在循环的版本，欢迎评论区交流。</p><hr><h2 id="出发-4-min" tabindex="-1">出发（4 min） <a class="header-anchor" href="#出发-4-min" aria-label="Permalink to &quot;出发（4 min）&quot;">​</a></h2><p><strong>1. 《群青》 YOASOBI</strong>——上车坐下戴耳机的固定仪式。前奏一响，世界切换频道。</p><p><strong>2. 某燃系动画 OP</strong>——早八人的启动键。副歌那声&quot;上吧&quot;我严重怀疑是唱给我背英语单词用的。</p><h2 id="中段-10-min" tabindex="-1">中段（10 min） <a class="header-anchor" href="#中段-10-min" aria-label="Permalink to &quot;中段（10 min）&quot;">​</a></h2><p><strong>3. Lo-fi 歌单</strong>——早上的城市还没完全醒，适合这种半梦半醒的曲子。</p><p><strong>4. 《打上花火》 DAOKO×米津玄师</strong>——没什么理由，就是好听。副歌升起烟花那一段，配上窗外刚亮的天，绝了。</p><p><strong>5. 某治愈系动画 ED</strong>——慢下来的一站。公交过桥的时候看江面，这首歌配这个画面，是每天最好的三十秒。</p><h2 id="到站前-9-min" tabindex="-1">到站前（9 min） <a class="header-anchor" href="#到站前-9-min" aria-label="Permalink to &quot;到站前（9 min）&quot;">​</a></h2><p><strong>6. 8-bit 风混音歌单</strong>——像素游戏的旋律配现代混音，听着听着就想起小学的电脑课。快到站那首鼓点密集，正好当&quot;起立铃&quot;。</p><p><strong>7. 常听的压轴曲</strong>——下车前最后一首固定留给它。像给这一天先定了个不错的底色。</p><div class="tip custom-block"><p class="custom-block-title">歌单管理守则</p><ul><li>一周换一版，跟不上了心情的歌进&quot;冷宫&quot;</li><li>音量永远 60%，要听得见报站——错过站的下场很惨（那次走到了邻校门口）</li><li>一天最多单曲循环三次，防止这首歌从此变成&quot;做题曲&quot;</li></ul></div><h2 id="一个小发现" tabindex="-1">一个小发现 <a class="header-anchor" href="#一个小发现" aria-label="Permalink to &quot;一个小发现&quot;">​</a></h2><p>长期听下来发现一个规律：<strong>早上听节奏快的，晚自习后听慢的</strong>，是效率最高的组合。反过来试过一次，早上犯困晚上亢奋，写作业写到凌晨一点，第二天语文课当场去世。</p><p>音乐是生活的调色盘，但调色之前，先看清今天是什么底色。</p><hr><p>你们上学路上都在听什么？评论区交换一首，我来者不拒。</p>',19)])])}const h=o(r,[["render",s]]);export{d as __pageData,h as default};
